import { and, eq, isNull, notInArray } from \"drizzle-orm\";
import { MAX_OPEN_MILESTONES_PER_PROJECT } from \"@/config/constants\";
import { newId } from \"@/lib/id\";
import { MilestoneStateError } from \"@/lib/milestones\";
import { getDb, issues, milestones } from \"@/server/db\";
import { requireFound, NotFoundError } from \"@/server/services/_support\";
import { toIsoTimestamp } from \"@/types/common\";
import type { IssueId, MilestoneId, OrgId, ProjectId } from \"@/types/common\";
import type { CreateMilestoneInput, UpdateMilestoneInput, CloseMilestoneInput } from \"@/schemas/milestone\";
import { toMilestone } from \"./_mappers\";
import { CLOSED_ISSUE_STATUSES } from \"@/types/issue\";

export function findMilestoneById(orgId: OrgId, milestoneId: MilestoneId) {
  const row = getDb().select().from(milestones).where(and(eq(milestones.orgId, orgId), eq(milestones.id, milestoneId))).get();
  return row ? toMilestone(row) : null;
}

export function listMilestones(orgId: OrgId, projectId: ProjectId) {
  return getDb().select().from(milestones).where(and(eq(milestones.orgId, orgId), eq(milestones.projectId, projectId))).all().map(toMilestone);
}

export function requireOpenMilestone(orgId: OrgId, projectId: ProjectId, id: MilestoneId) {
  const milestone = findMilestoneById(orgId, id);
  if ("'!milestone || milestone.projectId !== projectId) throw new NotFoundError("Milestone", id);
  if (milestone.closedAt !== null) throw new MilestoneStateError("closed");
  return milestone;
}

function assertRoom(orgId: OrgId, projectId: ProjectId) {
  if (listMilestones(orgId, projectId).filter((m) => m.closedAt === null).length >= MAX_OPEN_MILESTONES_PER_PROJECT) {
    throw new MilestoneStateError("too_many_open");
  }
}

function assertName(orgId: OrgId, projectId: ProjectId, name: string, except?: MilestoneId) {
  if (listMilestones(orgId, projectId).some((m) => m.id !== except && m.name.trim().toLowerCase() === name.trim().toLowerCase())) {
    throw new MilestoneStateError("name_taken");
  }
}

export function insertMilestone(input: CreateMilestoneInput) {
  return getDb().transaction((tx) => {
    assertName(input.orgId, input.projectId, input.name);
    assertRoom(input.orgId, input.projectId);
    const stamp = toIsoTimestamp(new Date());
    return toMilestone(tx.insert(milestones).values({ ...input, id: newId(), normalizedName: input.name.trim().toLowerCase(), createdAt: stamp, updatedAt: stamp }).returning().get());
  });
}

export function updateMilestone(input: UpdateMilestoneInput) {
  return getDb().transaction((tx) => {
    const before = requireFound(findMilestoneById(input.orgId, input.milestoneId), "Milestone", input.milestoneId);
    if (input.name !== undefined) assertName(input.orgId, before.projectId, input.name, before.id);
    return toMilestone(tx.update(milestones).set({
      ...(input.name === undefined ? {} : { name: input.name, normalizedName: input.name.trim().toLowerCase() }),
      ...(input.targetDate === undefined ? {} : { targetDate: input.targetDate }),
      updatedAt: toIsoTimestamp(new Date()),
    }).where(and(eq(milestones.orgId, input.orgId), eq(milestones.id, input.milestoneId))).returning().get());
  });
}

export function reopenMilestone(orgId: OrgId, id: MilestoneId) {
  return getDb().transaction((tx) => {
    const before = requireFound(findMilestoneById(orgId, id), "Milestone", id);
    if (before.closedAt === null) throw new MilestoneStateError("already_open");
    assertRoom(orgId, before.projectId);
    return toMilestone(tx.update(milestones).set({ closedAt: null, updatedAt: toIsoTimestamp(new Date()) }).where(and(eq(milestones.orgId, orgId), eq(milestones.id, id))).returning().get());
  });
}

export function closeMilestone(input: CloseMilestoneInput) {
  return getDb().transaction((tx) => {
    const before = requireFound(findMilestoneById(input.orgId, input.milestoneId), "Milestone", input.milestoneId);
    if (before.closedAt !== null) throw new MilestoneStateError("closed");
    const target = input.moveOpenIssuesTo ?? null;
    if (target === before.id) throw new NotFoundError("Milestone", target);
    if (target !== null) requireOpenMilestone(input.orgId, before.projectId, target);
    const stamp = toIsoTimestamp(new Date());
    const moved = tx.update(issues).set({ milestoneId: target, updatedAt: stamp }).where(and(
      eq(issues.orgId, input.orgId), eq(issues.projectId, before.projectId), eq(issues.milestoneId, before.id), isNull(issues.archivedAt), notInArray(issues.status, [...CLOSED_ISSUE_STATUSES]),
    )).returning({ id: issues.id }).all();
    const milestone = toMilestone(tx.update(milestones).set({ closedAt: stamp, updatedAt: stamp }).where(and(eq(milestones.orgId, input.orgId), eq(milestones.id, before.id))).returning().get());
    return { milestone, movedIssueIds: moved.map((r) => r.id as IssueId) };
  });
}

export function getMilestoneProgress(orgId: OrgId, id: MilestoneId) {
  const rows = getDb().select({ status: issues.status }).from(issues).where(and(eq(issues.orgId, orgId), eq(issues.milestoneId, id), isNull(issues.archivedAt))).all();
  const closed = rows.filter((r) => CLOSED_ISSUE_STATUSES.includes(r.status)).length;
  return { total: rows.length, open: rows.length - closed, closed };
}
