async function guardMilestone(actor: Actor, orgId: OrgId, id: MilestoneId, write: boolean) {
  assertOrgScope(actor, orgId);
  const milestone = requireFound(repo.findMilestoneById(orgId, id), \"Milestone\", id);
  await guardProject(actor, orgId, milestone.projectId, write);
  return milestone;
}

export async function createMilestone(actor: Actor, input: CreateMilestoneInput): Promise<Milestone> {
  await guardProject(actor, input.orgId, input.projectId, true);
  const milestone = repo.insertMilestone(input);
  await emit(\"milestone.created\", { ...actorEnvelope(actor), milestoneId: milestone.id, projectId: milestone.projectId });
  return milestone;
}

export async function updateMilestone(actor: Actor, input: UpdateMilestoneInput): Promise<Milestone> {
  await guardMilestone(actor, input.orgId, input.milestoneId, true);
  return repo.updateMilestone(input);
}

