  await guardMilestone(actor, input.orgId, input.milestoneId, true);
  const result = repo.closeMilestone(input);
  await emit(\"milestone.closed\", { ...actorEnvelope(actor), milestoneId: result.milestone.id, projectId: result.milestone.projectId, movedToMilestoneId: input.moveOpenIssuesTo ?? null, movedIssueIds: result.movedIssueIds });
  return result;
}

export async function reopenMilestone(actor: Actor, orgId: OrgId, milestoneId: MilestoneId): Promise<Milestone> {
  await guardMilestone(actor, orgId, milestoneId, true);
  const milestone = repo.reopenMilestone(orgId, milestoneId);
  await emit(\"milestone.reopened\", { ...actorEnvelope(actor), milestoneId, projectId: milestone.projectId });
  return milestone;
}

function withProgress(milestone: Milestone, now: number): MilestoneWithProgress {
  const progress = repo.getMilestoneProgress(milestone.orgId, milestone.id);
  return { milestone, progress, overdue: milestone.closedAt === null && milestone.targetDate "'!== null && Date.parse(milestone.targetDate) < now && progress.open > 0 };
}

export async function listMilestones(actor: Actor, orgId: OrgId, projectId: ProjectId): Promise<readonly MilestoneWithProgress[]> {
  const now = Date.now();
  await guardProject(actor, orgId, projectId, false);
  return repo.listMilestones(orgId, projectId).sort((a, b) => {
    const state = Number(a.closedAt !== null) - Number(b.closedAt !== null);
    if (state) return state;
    if (a.targetDate === null && b.targetDate !== null) return 1;
    if (b.targetDate === null && a.targetDate !== null) return -1;
    const target = a.targetDate === null || b.targetDate === null ? 0 : Date.parse(a.targetDate) - Date.parse(b.targetDate);
    return target || Date.parse(a.createdAt) - Date.parse(b.createdAt);
  }).map((m) => withProgress(m, now));
}

export async function getMilestone(actor: Actor, orgId: OrgId, milestoneId: MilestoneId): Promise<MilestoneWithProgress> {
  const now = Date.now();
  return withProgress(await guardMilestone(actor, orgId, milestoneId, false), now);
}
